=== commit-rules-guard ===
{
  "name": "commit-rules-guard",
  "description": "コミットルールを想起させ、動機の混在を気づかせるフック集 (セッション開始時・作業着手時・git commit 直前)",
  "version": "0.3.0",
  "author": {
    "name": "akm"
  },
  "license": "MIT"
}

  1	// judgment_flow.go は review-triage の判定フローの正本 (judgment-flow.md) について、
  2	// mermaid の図のノード ID 集合と決定表の ID 集合が 1:1 で一致するかを検査する
  3	// (judgment-flow)。
  4	//
  5	// 図は「ノードと遷移」だけ、表は「各ノードの条件と書くもの」だけを持ち、同じ事実を
  6	// 二度語らない。残るずれ方は ID 集合の不一致だけなので、そこを機械で照合する。
  7	// 生成はしない — 照合のみ。
  8	package main
  9	
 10	import (
 11		"errors"
 12		"fmt"
 13		"io/fs"
 14		"regexp"
 15		"sort"
 16		"strings"
 17	)
 18	
 19	// judgmentFlowPath は判定フローの正本。ファイルが存在しないときは検査を
 20	// 何もしない (対象は git 追跡でなくファイルの実在で決める)。
 21	//
 22	// スキルがプラグインとして配られると、この正本はリポジトリの外 (プラグインの
 23	// 展開先) に置かれ、パスは環境ごとに違う。main が CLAUDE_PLUGIN_ROOT または
 24	// -judgment-flow から解決して設定する。既定はリポジトリ内にスキルを直接置く
 25	// 形 (プラグイン化前の配置) で、そのときだけこの値がそのまま使われる。
 26	var judgmentFlowPath = ".claude/skills/review-triage/references/judgment-flow.md"
 27	
 28	var (
 29		// judgmentFlowIDRe はノード ID の形。判定 (D)・評価 (E)・採択 (A)・保留 (H)・却下 (R)。
 30		judgmentFlowIDRe = regexp.MustCompile(`\b([ADEHR]\d+)\b`)
 31		// judgmentFlowTableRowRe は決定表の行 (先頭セルが ID)。パイプ前後の空白の
 32		// 詰め方には依存しない。
 33		judgmentFlowTableRowRe = regexp.MustCompile(`^\|\s*([ADEHR]\d+)\s*\|`)
 34		// judgmentFlowQuoteRe は mermaid のラベル文字列。ID の抽出前に取り除く
 35		// (ラベル内の "D1: ..." のような表示用の ID を数えないため)。
 36		judgmentFlowQuoteRe = regexp.MustCompile(`"[^"]*"`)
 37		// judgmentFlowColorRe は色コード。`#A12` のような大文字の短い 16 進が
 38		// ID の形 ([ADEHR]\d+) に一致してしまうため、抽出前に取り除く (型 F の反例)。
 39		judgmentFlowColorRe = regexp.MustCompile(`#[0-9A-Fa-f]+`)
 40		// judgmentFlowSeparatorRe は表の区切り行 (| --- | --- |)。直前の行は見出しで、
 41		// 先頭セルが ID の形でも本体行として数えない。
 42		judgmentFlowSeparatorRe = regexp.MustCompile(`^\s*\|(\s*:?-{3,}:?\s*\|)+\s*$`)
 43	)
 44	
 45	// judgmentFlowDecorations は ID の出所にしない装飾行の先頭トークン。
 46	var judgmentFlowDecorations = map[string]bool{
 47		"style": true, "class": true, "classDef": true, "click": true, "linkStyle": true,
 48	}
 49	
 50	// judgmentFlowProblems は図と表の ID 集合を照合する。対象は git 追跡でなく
 51	// ファイルの実在で決める — 追跡前の判定フローが素通りする「0 件マッチで黙って緑」の
 52	// 型 (B1 と同じ) を塞ぐ。ファイルが無いのはスキル未導入の正常な状態で、何もしない。
 53	// files は他の検査とシグネチャを揃えるための引数で、使わない。
 54	func judgmentFlowProblems(_ []string, readFile func(string) ([]byte, error)) []string {
 55		data, err := readFile(judgmentFlowPath)
 56		if err != nil {
 57			if errors.Is(err, fs.ErrNotExist) {
 58				return nil
 59			}
 60			return []string{fmt.Sprintf("%s: 読み込みに失敗しました: %v", judgmentFlowPath, err)}
 61		}
 62	
 63		var problems []string
 64		diagramIDs := map[string]bool{}
 65		tableIDs := map[string]int{}
 66		inMermaid := false
 67		hasMermaid := false
 68		lines := strings.Split(string(data), "\n")
 69		for i, line := range lines {
 70			trimmed := strings.TrimSpace(line)
 71			switch {
 72			case strings.HasPrefix(trimmed, "```mermaid"):
 73				inMermaid = true
 74				hasMermaid = true
 75				continue
 76			case strings.HasPrefix(trimmed, "```"):
 77				inMermaid = false
 78				continue
 79			}
 80			if inMermaid {
 81				// コメント行 (%%。ディレクティブ %%{...}%% を含む) は ID の出所にしない。
 82				if strings.HasPrefix(trimmed, "%%") {
 83					continue
 84				}
 85				// 装飾の行も ID の出所にしない — ノードを消して style 行を消し忘れた
 86				// 編集ミスを、ID 照合が「図にある」と誤認しないため。先頭トークンは
 87				// strings.Fields で取り出す (タブ区切りも区切りとして扱う)。
 88				if fields := strings.Fields(trimmed); len(fields) > 0 && judgmentFlowDecorations[fields[0]] {
 89					continue
 90				}
 91				stripped := judgmentFlowQuoteRe.ReplaceAllString(line, "")
 92				stripped = judgmentFlowColorRe.ReplaceAllString(stripped, "")
 93				for _, m := range judgmentFlowIDRe.FindAllStringSubmatch(stripped, -1) {
 94					diagramIDs[m[1]] = true
 95				}
 96				continue
 97			}
 98			if m := judgmentFlowTableRowRe.FindStringSubmatch(line); m != nil {
 99				// 直後が区切り行なら、この行は見出し — 本体行として数えない。
100				if i+1 < len(lines) && judgmentFlowSeparatorRe.MatchString(lines[i+1]) {
101					continue
102				}
103				tableIDs[m[1]]++
104			}
105		}
106	
107		if !hasMermaid {
108			problems = append(problems, fmt.Sprintf("%s: mermaid の図が見つかりません (図がノードと遷移の正本)", judgmentFlowPath))
109		}
110		if len(tableIDs) == 0 {
111			problems = append(problems, fmt.Sprintf("%s: 決定表 (先頭セルが ID の行) が見つかりません", judgmentFlowPath))
112		}
113		if !hasMermaid || len(tableIDs) == 0 {
114			return problems
115		}
116	
117		for _, id := range sortedMapKeys(diagramIDs) {
118			if tableIDs[id] == 0 {
119				problems = append(problems, fmt.Sprintf(
120					"%s: %s は図にあるが決定表にありません (条件と書くものを表に足す)", judgmentFlowPath, id))
121			}
122		}
123		for id, n := range tableIDs {
124			if !diagramIDs[id] {
125				problems = append(problems, fmt.Sprintf(
126					"%s: %s は決定表にあるが図にありません (遷移を図に足すか行を消す)", judgmentFlowPath, id))
127			}
128			if n > 1 {
129				problems = append(problems, fmt.Sprintf(
130					"%s: %s の行が決定表で重複しています", judgmentFlowPath, id))
131			}
132		}
133		sort.Strings(problems)
134		return problems
135	}
136	
137	// sortedMapKeys はマップのキーを昇順で返す。出力の順序を入力の反復順に
138	// 依存させないため (問題の並びが実行ごとに変わると差分が読めない)。
139	func sortedMapKeys[V any](m map[string]V) []string {
140		keys := make([]string, 0, len(m))
141		for k := range m {
142			keys = append(keys, k)
143		}
144		sort.Strings(keys)
145		return keys
146	}

  1	// record.go はレビュー指摘のトリアージ記録 (docs/review-triage/*.yaml) の
  2	// スキーマと、生成サマリ (*.md) の鮮度を検査する (review-triage-record)。
  3	//
  4	// 記録の正本は YAML で、件数の集計・累計は人が書かず、サマリ生成が計算する。
  5	// 1 回目の試行 (claude/review-triage-skill-bf7714) では手書きの累計・ピン値の
  6	// 誤りが指摘の約 3 分の 1 を占め、書かせて検算する検査は「正しい訂正手順が
  7	// 偽赤になる」穴を生んだ。数えるものを書かせないことで、この類を発生源から消す。
  8	// スキーマの意味の正本は docs/review-triage/README.md。
  9	package main
 10	
 11	import (
 12		"bytes"
 13		"errors"
 14		"fmt"
 15		"io"
 16		"io/fs"
 17		"os"
 18		"path"
 19		"regexp"
 20		"sort"
 21		"strconv"
 22		"strings"
 23	
 24		"gopkg.in/yaml.v3"
 25	)
 26	
 27	// reviewTriageDir はトリアージの記録の置き場。この変数が唯一の定義 —
 28	// 別のリテラルを増やすと、移設のとき片方だけ更新されて検査が黙って外れる。
 29	//
 30	// 既定は docs/review-triage/ で、-record-dir で上書きできる (リポジトリごとに
 31	// 置き場が違うため)。末尾のスラッシュは main が正規化して必ず付ける —
 32	// HasPrefix の照合が接頭辞の一致に依存しており、無いと docs/review-triage-old/
 33	// のような別ディレクトリまで拾う。
 34	var reviewTriageDir = "docs/review-triage/"
 35	
 36	// --- スキーマ (意味の正本は docs/review-triage/README.md) ---
 37	
 38	type recordDoc struct {
 39		Runs []recordRun `yaml:"runs"`
 40	}
 41	
 42	type recordRun struct {
 43		Date     string          `yaml:"date"`
 44		Skill    string          `yaml:"skill"`
 45		RunID    string          `yaml:"run_id"`
 46		Model    string          `yaml:"model"`
 47		Level    string          `yaml:"level"`
 48		Scope    string          `yaml:"scope"`
 49		Head     string          `yaml:"head"`
 50		Findings []recordFinding `yaml:"findings"`
 51		Plans    []recordPlan    `yaml:"plans"`
 52		Notes    string          `yaml:"notes"`
 53	}
 54	
 55	type recordFinding struct {
 56		ID              int               `yaml:"id"`
 57		File            string            `yaml:"file"`
 58		Line            int               `yaml:"line"`
 59		Summary         string            `yaml:"summary"`
 60		Category        string            `yaml:"category"`
 61		Audience        string            `yaml:"audience"`
 62		AudienceInitial string            `yaml:"audience_initial"`
 63		Consequence     recordConsequence `yaml:"consequence"`
 64		PremiseCheck    recordPremise     `yaml:"premise_check"`
 65		GatesFired      []string          `yaml:"gates_fired"`
 66		Verdict         string            `yaml:"verdict"`
 67		VerdictReason   string            `yaml:"verdict_reason"`
 68		PlanRef         *recordPlanRef    `yaml:"plan_ref"`
 69		Attrs           map[string]any    `yaml:"attrs"`
 70	}
 71	
 72	type recordConsequence struct {
 73		Condition     string `yaml:"condition"`
 74		Who           string `yaml:"who"`
 75		What          string `yaml:"what"`
 76		Detectability string `yaml:"detectability"`
 77	}
 78	
 79	type recordPremise struct {
 80		Stages string `yaml:"stages"`
 81		Result string `yaml:"result"`
 82	}
 83	
 84	// recordPlanRef は採択の束ね先 (どの回のどの問題で直すか) の構造化参照。
 85	// 回をまたいで同因の指摘を束ねたとき (並列レビューの運用)、対応関係を
 86	// 自由記述でなく機械で辿れる形で残す。run は同じファイル内の 1 始まりの回番号。
 87	type recordPlanRef struct {
 88		Run     int    `yaml:"run"`
 89		Problem string `yaml:"problem"`
 90	}
 91	
 92	type recordPlan struct {
 93		ProblemID  string   `yaml:"problem_id"`
 94		Cause      string   `yaml:"cause"`
 95		FindingIDs []int    `yaml:"finding_ids"`
 96		Approach   string   `yaml:"approach"`
 97		Options    string   `yaml:"options"`
 98		Order      int      `yaml:"order"`
 99		DependsOn  []string `yaml:"depends_on"`
100		SHA        string   `yaml:"sha"`
101		Status     string   `yaml:"status"`
102	}
103	
104	// recordAllowedKeys は階層ごとに許すキー。未知のキーは報告する — 旧いキー名の
105	// 残存が「エラーなしで空」に化ける型を避けるため。attrs だけは任意のキーを許す
106	// (上流固有の属性のパススルー)。
107	var recordAllowedKeys = map[string]map[string]bool{
108		"トップレベル": {"runs": true},
109		"実行": {"date": true, "skill": true, "run_id": true, "model": true, "level": true,
110			"scope": true, "head": true, "findings": true, "plans": true, "notes": true},
111		"指摘": {"id": true, "file": true, "line": true, "summary": true, "category": true,
112			"audience": true, "audience_initial": true, "consequence": true, "premise_check": true,
113			"gates_fired": true, "verdict": true, "verdict_reason": true, "plan_ref": true, "attrs": true},
114		"束ね先":   {"run": true, "problem": true},
115		"帰結":    {"condition": true, "who": true, "what": true, "detectability": true},
116		"根拠の検証": {"stages": true, "result": true},
117		"修正計画": {"problem_id": true, "cause": true, "finding_ids": true, "approach": true,
118			"options": true, "order": true, "depends_on": true, "sha": true, "status": true},
119	}
120	
121	// reviewTriageRecordProblems は docs/review-triage/ の記録 YAML を検査する。
122	// README.md は対象外。検査は (1) スキーマ (未知キー・必須キー・列挙値・参照の整合)、
123	// (2) サマリの鮮度 (YAML から生成した内容と *.md の一致)、(3) 孤児のサマリ。
124	func reviewTriageRecordProblems(files []string, readFile func(string) ([]byte, error)) []string {
125		var problems []string
126		fileSet := make(map[string]bool, len(files))
127		for _, f := range files {
128			fileSet[f] = true
129		}
130		var stems []string
131		var mds []string
132		for _, f := range files {
133			if !strings.HasPrefix(f, reviewTriageDir) || path.Base(f) == "README.md" {
134				continue
135			}
136			switch {
137			case strings.HasSuffix(f, ".yaml"):
138				stems = append(stems, strings.TrimSuffix(f, ".yaml"))
139			case strings.HasSuffix(f, ".md"):
140				mds = append(mds, f)
141			}
142		}
143		sort.Strings(stems)
144		stemSet := make(map[string]bool, len(stems))
145		for _, s := range stems {
146			stemSet[s] = true
147		}
148	
149		for _, stem := range stems {
150			yf := stem + ".yaml"
151			data, err := readFile(yf)
152			if err != nil {
153				problems = append(problems, fmt.Sprintf("%s: 読み込みに失敗しました: %v", yf, err))
154				continue
155			}
156			ps, doc := recordProblemsInYAML(yf, data)
157			problems = append(problems, ps...)
158	
159			// サマリの鮮度。スキーマに問題がある間は比較しない (直せば両方直る)。
160			mdPath := stem + ".md"
161			if !fileSet[mdPath] {
162				problems = append(problems, fmt.Sprintf(
163					"%s: サマリ %s がありません (`make docs-review-triage-summary` で生成してコミットする)", yf, mdPath))
164				continue
165			}
166			if len(ps) > 0 || doc == nil {
167				continue
168			}
169			want := renderReviewTriageSummaryDoc(yf, doc)
170			got, err := readFile(mdPath)
171			if err != nil {
172				problems = append(problems, fmt.Sprintf("%s: 読み込みに失敗しました: %v", mdPath, err))
173				continue
174			}
175			if string(got) != want {
176				problems = append(problems, fmt.Sprintf(
177					"%s: サマリが正本 (%s) と食い違っています (`make docs-review-triage-summary` で再生成する)", mdPath, yf))
178			}
179		}
180	
181		sort.Strings(mds)
182		for _, md := range mds {
183			if !stemSet[strings.TrimSuffix(md, ".md")] {
184				problems = append(problems, fmt.Sprintf(
185					"%s: 対応する YAML (正本) がありません。記録の正本は <ブランチ名>.yaml で、サマリはその生成物", md))
186			}
187		}
188		return problems
189	}
190	
191	// recordLineCommentProblems は行内コメント (LineComment) を持つノードを検出する。
192	// YAML の素のスカラーは半角スペースに続く # 以降をコメントとして落とすため、
193	// 引用符の無い値に # を書くと値が黙って切り詰められる (実測で cause が「PR」だけに
194	// なった)。切り詰められた分はパーサが LineComment として保持するので、そこを見る —
195	// 生テキストの正規表現で字句規則を再現する方式は、キーの形・空白・ブロックスカラー・
196	// 値全体のコメントと境界のたびに穴が開いた (列挙する検査は穴を再生産する既知の型)。
197	// ブロックスカラーの本文の # は内容でありコメントにならないので、構造的に区別される。
198	// 行頭コメント (HeadComment) は値を壊さないため対象にしない。
199	func recordLineCommentProblems(f string, root *yaml.Node) []string {
200		var problems []string
201		var walk func(n *yaml.Node)
202		walk = func(n *yaml.Node) {
203			if n.LineComment != "" {
204				problems = append(problems, fmt.Sprintf(
205					"%s:%d: 行内コメント (%q) は使えません — YAML は ' #' 以降をコメントとして落とし、値が黙って切り詰められる。値に # を含めるときは引用符で囲む",
206					f, n.Line, n.LineComment))
207			}
208			for _, c := range n.Content {
209				walk(c)
210			}
211		}
212		walk(root)
213		return problems
214	}
215	
216	// recordProblemsInYAML は 1 ファイル分のスキーマ検査を行い、問題と (読めた場合の) 文書を返す。
217	func recordProblemsInYAML(f string, data []byte) ([]string, *recordDoc) {
218		var root yaml.Node
219		dec := yaml.NewDecoder(bytes.NewReader(data))
220		if err := dec.Decode(&root); err != nil {
221			// 空・コメントのみ・空白のみは EOF になる。生の文言では実際の状態が読めない。
222			if errors.Is(err, io.EOF) {
223				return []string{fmt.Sprintf("%s: 記録が空です (runs がありません)", f)}, nil
224			}
225			return []string{fmt.Sprintf("%s: YAML を解析できません: %v", f, err)}, nil
226		}
227		// 記録は単一ドキュメント。--- 区切りの 2 つ目以降は読まれずに消えるため、存在自体を弾く。
228		var extra yaml.Node
229		if err := dec.Decode(&extra); err == nil {
230			return []string{fmt.Sprintf(
231				"%s: --- 区切りの 2 つ目のドキュメントがあります — 記録は単一ドキュメントで、2 つ目以降は読まれず消える", f)}, nil
232		} else if !errors.Is(err, io.EOF) {
233			return []string{fmt.Sprintf("%s: 2 つ目のドキュメントの解析に失敗しました: %v", f, err)}, nil
234		}
235		if len(root.Content) == 0 ||
236			(root.Content[0].Kind == yaml.ScalarNode && root.Content[0].Tag == "!!null") {
237			// null・~・--- だけのファイルは null スカラーのルートとして解析され、
238			// EOF にも空 Content にもならない。実質的に空なので同じ文言に揃える。
239			return []string{fmt.Sprintf("%s: 記録が空です (runs がありません)", f)}, nil
240		}
241		problems := recordLineCommentProblems(f, &root)
242		problems = append(problems, recordUnknownKeyProblems(f, root.Content[0])...)
243		var doc recordDoc
244		if err := root.Decode(&doc); err != nil {
245			problems = append(problems, fmt.Sprintf("%s: スキーマに合いません: %v", f, err))
246			return problems, nil
247		}
248		problems = append(problems, recordSemanticProblems(f, &doc)...)
249		return problems, &doc
250	}
251	
252	// recordUnknownKeyProblems は許可キー集合との突き合わせで未知のキーを列挙する。
253	// 未知のキーが見つかっても走査を続け、他の問題の報告を妨げない。
254	func recordUnknownKeyProblems(f string, n *yaml.Node) []string {
255		var problems []string
256		var walkMap func(n *yaml.Node, kind string)
257		walkSeq := func(n *yaml.Node, kind string) {
258			if n == nil || n.Kind != yaml.SequenceNode {
259				return
260			}
261			for _, item := range n.Content {
262				walkMap(item, kind)
263			}
264		}
265		walkMap = func(n *yaml.Node, kind string) {
266			if n == nil || n.Kind != yaml.MappingNode {
267				return
268			}
269			allowed := recordAllowedKeys[kind]
270			for i := 0; i+1 < len(n.Content); i += 2 {
271				k, v := n.Content[i], n.Content[i+1]
272				if !allowed[k.Value] {
273					problems = append(problems, fmt.Sprintf(
274						"%s:%d: %sに未知のキー %q。旧いキー名の残存か置き場の誤り (上流固有の属性は attrs へ) を疑う",
275						f, k.Line, kind, k.Value))
276					continue
277				}
278				switch k.Value {
279				case "runs":
280					walkSeq(v, "実行")
281				case "findings":
282					walkSeq(v, "指摘")
283				case "plans":
284					walkSeq(v, "修正計画")
285				case "consequence":
286					walkMap(v, "帰結")
287				case "premise_check":
288					walkMap(v, "根拠の検証")
289				case "plan_ref":
290					walkMap(v, "束ね先")
291				}
292			}
293		}
294		walkMap(n, "トップレベル")
295		return problems
296	}
297	
298	var recordDateRe = regexp.MustCompile(`^\d{4}-\d{2}-\d{2}$`)
299	
300	// recordAudiences は被害者の列挙 (glossary のロール + 開発者)。設定 (.claude/review-triage.yaml)
301	// の audience と同じ値域。
302	var recordAudiences = map[string]bool{
303		"operator": true, "admin": true, "provider": true, "developer": true,
304	}
305	
306	// recordSemanticProblems は必須キー・列挙値・参照の整合を検査する。
307	func recordSemanticProblems(f string, doc *recordDoc) []string {
308		var problems []string
309		add := func(format string, args ...any) {
310			problems = append(problems, f+": "+fmt.Sprintf(format, args...))
311		}
312		if len(doc.Runs) == 0 {
313			add("runs がありません (実行が 1 つも無い)")
314		}
315		// 回ごとの問題 id の索引 (plan_ref の解決と被覆の検査に使う)。
316		plansByRun := make([]map[string]bool, len(doc.Runs))
317		for ri, run := range doc.Runs {
318			plansByRun[ri] = map[string]bool{}
319			for _, pl := range run.Plans {
320				plansByRun[ri][pl.ProblemID] = true
321			}
322		}
323		for ri, run := range doc.Runs {
324			rn := fmt.Sprintf("runs[%d] (%s %s)", ri, run.Date, run.Skill)
325			if !recordDateRe.MatchString(run.Date) {
326				add("%s: date が YYYY-MM-DD ではありません: %q", rn, run.Date)
327			}
328			if run.Skill == "" {
329				add("%s: skill がありません", rn)
330			}
331			if run.Model == "" {
332				add("%s: model がありません (レビューを実行したモデルを必ず残す)", rn)
333			}
334			if run.Scope != "incremental" && run.Scope != "full" {
335				add("%s: scope は incremental / full のいずれか: %q", rn, run.Scope)
336			}
337			if run.Head == "" {
338				add("%s: head がありません (レビュー時点の短縮 SHA)", rn)
339			}
340	
341			verdictByID := map[int]string{}
342			for fi, fd := range run.Findings {
343				fn := fmt.Sprintf("%s: findings[%d] (id %d)", rn, fi, fd.ID)
344				if fd.ID <= 0 {
345					add("%s: id は正の整数にする", fn)
346				} else if _, dup := verdictByID[fd.ID]; dup {
347					add("%s: id が同じ回の中で重複しています", fn)
348				}
349				verdictByID[fd.ID] = fd.Verdict
350				for _, kv := range []struct{ key, val string }{
351					{"file", fd.File}, {"summary", fd.Summary},
352					{"category", fd.Category}, {"audience", fd.Audience},
353				} {
354					if kv.val == "" {
355						add("%s: %s がありません", fn, kv.key)
356					}
357				}
358				// audience の列挙。列挙外の値が黙って通ると D7 (被害者の判定) の入力が壊れる。
359				if fd.Audience != "" && !recordAudiences[fd.Audience] {
360					add("%s: audience は operator / admin / provider / developer のいずれか: %q", fn, fd.Audience)
361				}
362				if fd.AudienceInitial != "" && !recordAudiences[fd.AudienceInitial] {
363					add("%s: audience_initial は operator / admin / provider / developer のいずれか: %q", fn, fd.AudienceInitial)
364				}
365				for _, kv := range []struct{ key, val string }{
366					{"condition", fd.Consequence.Condition}, {"who", fd.Consequence.Who},
367					{"what", fd.Consequence.What}, {"detectability", fd.Consequence.Detectability},
368				} {
369					if kv.val == "" {
370						add("%s: consequence.%s がありません (帰結の 4 項目は必須)", fn, kv.key)
371					}
372				}
373				switch fd.PremiseCheck.Stages {
374				case "none", "A", "A+B":
375				default:
376					add("%s: premise_check.stages は none / A / A+B のいずれか: %q", fn, fd.PremiseCheck.Stages)
377				}
378				switch fd.PremiseCheck.Result {
379				case "verified", "wrong", "unverifiable", "skipped":
380				default:
381					add("%s: premise_check.result は verified / wrong / unverifiable / skipped のいずれか: %q",
382						fn, fd.PremiseCheck.Result)
383				}
384				if (fd.PremiseCheck.Stages == "none") != (fd.PremiseCheck.Result == "skipped") {
385					add("%s: stages が none のときだけ result は skipped (stages %q / result %q)",
386						fn, fd.PremiseCheck.Stages, fd.PremiseCheck.Result)
387				}
388				switch fd.Verdict {
389				case "adopted", "held", "rejected":
390				default:
391					add("%s: verdict は adopted / held / rejected のいずれか: %q", fn, fd.Verdict)
392				}
393				if fd.VerdictReason == "" {
394					add("%s: verdict_reason がありません (判定の経路をノード ID で書く)", fn)
395				}
396				if fd.PlanRef != nil {
397					if fd.PlanRef.Run < 1 || fd.PlanRef.Run > len(doc.Runs) {
398						add("%s: plan_ref の run %d は存在しません (回は 1〜%d)", fn, fd.PlanRef.Run, len(doc.Runs))
399					} else if !plansByRun[fd.PlanRef.Run-1][fd.PlanRef.Problem] {
400						add("%s: plan_ref の問題 %q は回 %d の plans にありません", fn, fd.PlanRef.Problem, fd.PlanRef.Run)
401					}
402				}
403			}
404	
405			problemIDs := map[string]bool{}
406			for _, pl := range run.Plans {
407				if pl.ProblemID != "" && problemIDs[pl.ProblemID] {
408					add("%s: problem_id %q が重複しています", rn, pl.ProblemID)
409				}
410				problemIDs[pl.ProblemID] = true
411			}
412			for pi, pl := range run.Plans {
413				pn := fmt.Sprintf("%s: plans[%d] (%s)", rn, pi, pl.ProblemID)
414				for _, kv := range []struct{ key, val string }{
415					{"problem_id", pl.ProblemID}, {"cause", pl.Cause}, {"approach", pl.Approach},
416				} {
417					if kv.val == "" {
418						add("%s: %s がありません", pn, kv.key)
419					}
420				}
421				if len(pl.FindingIDs) == 0 {
422					add("%s: finding_ids がありません (1 つ以上)", pn)
423				}
424				for _, id := range pl.FindingIDs {
425					v, ok := verdictByID[id]
426					if !ok {
427						add("%s: finding_ids の %d は同じ回の findings にありません", pn, id)
428					} else if v != "adopted" {
429						add("%s: finding_ids の %d は採択 (adopted) ではありません (verdict %s)。修正計画は採択だけを束ねる", pn, id, v)
430					}
431				}
432				switch pl.Status {
433				case "pending", "awaiting-human":
434					if pl.SHA != "" {
435						add("%s: status %s なのに sha %q があります。直したのなら status: done にする", pn, pl.Status, pl.SHA)
436					}
437					if pl.Status == "awaiting-human" && pl.Options == "" {
438						add("%s: status awaiting-human には options (選択肢とトレードオフ) が必須", pn)
439					}
440				case "done":
441					if pl.SHA == "" {
442						add("%s: status done には sha (短縮 SHA) が必須", pn)
443					}
444				default:
445					add("%s: status は pending / awaiting-human / done のいずれか: %q", pn, pl.Status)
446				}
447				for _, d := range pl.DependsOn {
448					if d == pl.ProblemID {
449						add("%s: depends_on が自己参照しています", pn)
450						continue
451					}
452					if !problemIDs[d] {
453						add("%s: depends_on の %q は同じ回の plans にありません", pn, d)
454					}
455				}
456			}
457			// 被覆: 修正計画を書いた回では、採択は自回の plans か plan_ref で覆われる。
458			// 覆われない採択は、対処しないまま黙って消える。plans が無い回は fix 前なので
459			// 要求しない。
460			if len(run.Plans) > 0 {
461				covered := map[int]bool{}
462				for _, pl := range run.Plans {
463					for _, id := range pl.FindingIDs {
464						covered[id] = true
465					}
466				}
467				for _, fd := range run.Findings {
468					if fd.Verdict != "adopted" || covered[fd.ID] {
469						continue
470					}
471					if fd.PlanRef != nil {
472						continue // 参照自体の実在は上の finding ループで検査済み
473					}
474					add("%s: findings id %d: 採択が修正計画に載っていません (自回の plans にも plan_ref にも無い)", rn, fd.ID)
475				}
476			}
477			for _, cycle := range recordDependsOnCycles(run.Plans) {
478				add("%s: depends_on が循環しています (%s)。順序が定まらない — 同じ原因の 1 問題に束ねるべきものを分けていないかを疑う",
479					rn, strings.Join(cycle, " → "))
480			}
481		}
482		return problems
483	}
484	
485	// recordDependsOnCycles は plans の depends_on の循環を検出する。自己参照は
486	// 個別に報告するのでここでは扱わない。同じ循環は 1 度だけ返す。
487	func recordDependsOnCycles(plans []recordPlan) [][]string {
488		deps := make(map[string][]string, len(plans))
489		for _, pl := range plans {
490			for _, d := range pl.DependsOn {
491				if d != pl.ProblemID {
492					deps[pl.ProblemID] = append(deps[pl.ProblemID], d)
493				}
494			}
495		}
496		const (
497			visiting = 1
498			done     = 2
499		)
500		state := map[string]int{}
501		var cycles [][]string
502		var stack []string
503		var visit func(id string)
504		visit = func(id string) {
505			state[id] = visiting
506			stack = append(stack, id)
507			for _, d := range deps[id] {
508				switch state[d] {
509				case 0:
510					visit(d)
511				case visiting:
512					// stack の d 以降が循環。
513					for i, s := range stack {
514						if s == d {
515							cycle := append(append([]string{}, stack[i:]...), d)
516							cycles = append(cycles, cycle)
517							break
518						}
519					}
520				}
521			}
522			stack = stack[:len(stack)-1]
523			state[id] = done
524		}
525		for _, pl := range plans {
526			if state[pl.ProblemID] == 0 {
527				visit(pl.ProblemID)
528			}
529		}
530		return cycles
531	}
