533	// --- サマリの生成 ---
534	
535	// renderReviewTriageSummary は記録 YAML から人が読むサマリ (Markdown) を生成する。
536	// 件数はすべてここで計算する — 人が書いた集計をどこからも読まない。
537	func renderReviewTriageSummary(yamlPath string, data []byte) (string, error) {
538		var doc recordDoc
539		if err := yaml.Unmarshal(data, &doc); err != nil {
540			return "", fmt.Errorf("%s: YAML を読めません: %w", yamlPath, err)
541		}
542		return renderReviewTriageSummaryDoc(yamlPath, &doc), nil
543	}
544	
545	func renderReviewTriageSummaryDoc(yamlPath string, doc *recordDoc) string {
546		base := path.Base(yamlPath)
547		stem := strings.TrimSuffix(base, ".yaml")
548		var b strings.Builder
549		fmt.Fprintf(&b, "<!-- 生成物。手で編集しない。正本は %s — `make docs-review-triage-summary` で再生成する。 -->\n\n", base)
550		fmt.Fprintf(&b, "# %s のトリアージ記録\n\n", stem)
551		fmt.Fprintf(&b, "正本は [%s](%s)。読み方と収束の目安は [README](README.md)。\n\n", base, base)
552	
553		b.WriteString("## 推移\n\n")
554		b.WriteString("| 回 | 日付 | スキル | model | scope | 全件 | 採択 | 保留 | 却下 |\n")
555		b.WriteString("| --- | --- | --- | --- | --- | --- | --- | --- | --- |\n")
556		for i, run := range doc.Runs {
557			adopted, held, rejected := 0, 0, 0
558			for _, fd := range run.Findings {
559				switch fd.Verdict {
560				case "adopted":
561					adopted++
562				case "held":
563					held++
564				case "rejected":
565					rejected++
566				}
567			}
568			// 自由文字列の欄 (skill・model など) は recordCell で無害化する — 縦棒が
569			// 入ると桁がずれ、偽の数字が集計値の手前に並ぶ (列挙で守られない欄は検査も
570			// 捕まえない)。
571			fmt.Fprintf(&b, "| %d | %s | `%s` | `%s` | %s | %d | %d | %d | %d |\n",
572				i+1, recordCell(run.Date), recordCell(run.Skill), recordCell(run.Model),
573				recordCell(run.Scope), len(run.Findings), adopted, held, rejected)
574		}
575	
576		for i, run := range doc.Runs {
577			fmt.Fprintf(&b, "\n## 回 %d: %s `%s`", i+1, recordCell(run.Date), recordCell(run.Skill))
578			if run.RunID != "" {
579				fmt.Fprintf(&b, " (%s)", recordCell(run.RunID))
580			}
581			b.WriteString("\n\n")
582			fmt.Fprintf(&b, "- HEAD `%s` / model `%s` / scope %s",
583				recordCell(run.Head), recordCell(run.Model), recordCell(run.Scope))
584			if run.Level != "" {
585				b.WriteString(" / level " + recordCell(run.Level))
586			}
587			b.WriteString("\n\n")
588	
589			b.WriteString("| # | 指摘 | 分類 / 被害者 | 帰結 (条件 / 何が / 気づけるか) | 検証 | ゲート | 判定 |\n")
590			b.WriteString("| --- | --- | --- | --- | --- | --- | --- |\n")
591			for _, fd := range run.Findings {
592				b.WriteString(recordRow(renderFindingCells(fd)))
593			}
594	
595			if len(run.Plans) > 0 {
596				b.WriteString("\n### 修正計画\n\n")
597				b.WriteString("| 問題 | 原因 | 含む指摘 | 修正方法 | 順 | 状態 | SHA |\n")
598				b.WriteString("| --- | --- | --- | --- | --- | --- | --- |\n")
599				for _, pl := range run.Plans {
600					b.WriteString(recordRow(renderPlanCells(pl)))
601				}
602				for _, pl := range run.Plans {
603					if pl.Status == "awaiting-human" {
604						fmt.Fprintf(&b, "\n- **%s は選択待ち (人間が選ぶ)**: %s\n", recordCell(pl.ProblemID), recordCell(pl.Options))
605					}
606				}
607			}
608	
609			if run.Notes != "" {
610				b.WriteString("\n### 観察\n\n" + strings.TrimRight(run.Notes, "\n") + "\n")
611			}
612		}
613		return b.String()
614	}
