616	// recordRow はセルの列から表の 1 行を組み立てる。
617	func recordRow(cells []string) string {
618		return "| " + strings.Join(cells, " | ") + " |\n"
619	}
620	
621	// renderFindingCells は指摘 1 件の表のセル列を返す。行を 1 つの書式文字列で
622	// 組み立てると、テストがセル単位で分岐を検証できず、存在確認のアサーションが
623	// 別のセルへの偶然一致で通り抜ける (実測で 3 度起きた型)。
624	func renderFindingCells(fd recordFinding) []string {
625		loc := fd.File
626		if fd.Line > 0 {
627			loc = fmt.Sprintf("%s:%d", fd.File, fd.Line)
628		}
629		aud := fd.Audience
630		if fd.AudienceInitial != "" && fd.AudienceInitial != fd.Audience {
631			aud = fd.AudienceInitial + " → " + fd.Audience
632		}
633		premise := "対象外"
